export const COBBLEMON_DROPS: PokemonDrop[] = COBBLEMON_DROPS_DATASET;

export function getDropsForPokemon(pokemonId: string): PokemonDrop | undefined {
  const q = pokemonId.toLowerCase().trim();
  return COBBLEMON_DROPS_DATASET.find(d => d.pokemonId.toLowerCase() === q || d.pokemonName.toLowerCase() === q);
}
